L000033	\title{Altermagnetic and dipolar splitting of magnons in FeF$_2$}
L000034	
L000035	
L000036	\author{J. Sears\orcidlink{0000-0001-6524-8953}}
L000037	\email{jsears@bnl.gov}
L000038	\affiliation{Condensed Matter Physics and Materials Science Division, Brookhaven National Laboratory, Upton, New York 11973-5000, USA}
